const ticket = String($json.ticket || '').toLowerCase();
const highRiskTerms = ['production down','complete outage','security breach','data loss','data corruption','credential leak'];
const highRisk = highRiskTerms.find(term => ticket.includes(term));
let severity = 'P3';
let category = 'integration';
let reason = 'Standard support investigation';
if (highRisk) { severity = 'P1'; category = 'availability_or_security'; reason = `High-risk signal: ${highRisk}`; }
else if (ticket.includes('401') || ticket.includes('unauthorized')) { severity = 'P2'; category = 'authentication'; reason = 'Authentication failure after credential rotation'; }
else if (ticket.includes('504') || ticket.includes('timeout')) { severity = 'P2'; category = 'performance'; reason = 'Timeout or upstream latency signal'; }
else if (ticket.includes('429')) { severity = 'P3'; category = 'rate_limit'; reason = 'Rate-limit signal'; }
return [{ json: { ...$json, severity, category, reason, escalate: severity === 'P1', human_approval_required: severity === 'P1' } }];

const valid = ['P1','P2','P3','P4'].includes($json.severity) && Boolean($json.category);
if (!valid) throw new Error('Verification failed: invalid routing output');
return [{ json: { verification: 'PASS', orchestration: 'n8n trigger -> normalization -> classification -> deterministic guardrail -> human routing', severity: $json.severity, category: $json.category, escalate: Boolean($json.escalate), human_approval_required: Boolean($json.human_approval_required), reason: $json.reason, checked_at: new Date().toISOString() } }];
